head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getMediaInfo]<br/>현재 페이지에 설정된 적응형(adaptive) 미디어 정보를 JSON 객체 형태로 반환합니다.",
    "validation" : [
        "반환 객체의 currentScreen 속성으로 현재 브라우저 크기에 맞는 screen 이름을 확인할 수 있어야 합니다.",
        "미디어 정보가 없는 경우 currentScreen 은 null 값을 가져야 합니다.",
        "반환 객체의 mediaInfo 속성으로 각 screen 정보 객체의 배열을 확인할 수 있어야 합니다.",
        "mediaInfo 배열의 각 요소는 name, viewport, pageSize 속성을 가져야 합니다.",
        "viewport 속성값은 'x' 로 분리한 배열이어야 합니다.",
        "pageSize 속성값은 'x' 로 분리한 배열이어야 합니다.",
        "미디어 정보가 없는 경우 mediaInfo 는 빈 배열을 가져야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createLabel('label="screen 설정: mobile(480x800), tablet(768x1024), desktop(1280x720)"', '', 'label1');
};



scwin.btn_getMediaInfo_onclick = function () {
    let mediaObj = WebSquare.util.getMediaInfo();

    let result = [];
    result.push("currentScreen : " + mediaObj.currentScreen);
    result.push("mediaInfo 개수 : " + mediaObj.mediaInfo.length);

    for (let i = 0; i < mediaObj.mediaInfo.length; i++) {
        let info = mediaObj.mediaInfo[i];
        result.push("[" + i + "] name: " + info.name + ", viewport: [" + info.viewport.join(", ") + "], pageSize: [" + info.pageSize.join(", ") + "]");
    }

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
